import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        if any(x < 2 for x in A):
            results.append("-1")
        else:
            total_sum = sum(A)
            count_ge_2 = sum(1 for x in A if x >= 2)
            ans = total_sum - count_ge_2 + 2 * N
            results.append(str(ans))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
